"""Actual candidate generated bytes + fake Node, not final package/HIL proof."""
from dataclasses import fields, replace
import math
import unittest
from unittest.mock import patch

import flatbuffers
from lowlevel.GripperCmd import GripperCmd as WireCmd, GripperCmdT
from lowlevel.GripperInfo import GripperInfo as WireInfo, GripperInfoT
from lowlevel.GripperState import GripperState as WireState, GripperStateT
from lowlevel.GripperSample import GripperSample as WireSample, GripperSampleT
from lowlevel.GripperHostTarget import GripperHostTarget as WireTarget, GripperHostTargetT
from lowlevel.GripperLimitSource import GripperLimitSource

from locomotion_aorta import _gripper_codec as codec
from locomotion_aorta.gripper import GripperClient
from locomotion_aorta.gripper_types import GripperCmd, GripperState
from test_gripper_lifecycle import FakeNode, Handle


def pack(obj):
    builder = flatbuffers.Builder(512)
    builder.Finish(obj.Pack(builder))
    return bytes(builder.Output())


class RealPublisher(Handle):
    def __init__(self, node, meta):
        super().__init__()
        self.node, self.meta = node, meta

    def publish_typed(self, fill):
        builder = flatbuffers.Builder(128)
        builder.Finish(fill(builder, 0))
        self.node.payloads.append(bytes(builder.Output()))


class RealPacketNode(FakeNode):
    def __init__(self):
        super().__init__()
        self.payloads = []

    def create_publisher_typed(self, meta, topic, qos):
        if topic != '/sdk/foot_humanoid/gripper/left/cmd' or meta.ROOT_TYPE_NAME != 'lowlevel.GripperCmd':
            raise AssertionError('unexpected topic/metadata')
        h = RealPublisher(self, meta)
        self.handles.append(h)
        return h


class CodecTest(unittest.TestCase):
    def test_generated_nullable_roundtrip_none_zero_signed_and_envelope(self):
        wire = codec.load_bindings()
        command = GripperCmd(2**63 + 11, 2**63 + 12, 1, 2, .0625, 0.,
                            input_state_id=2**63 + 13, input_state_ts_real_us=1792000000000000,
                            ts_client_created_us=1792000000001000, ts_client_send_us=1792000000001010,
                            cmd_id=65535)
        for torque in (None, 0., -.25, .5):
            with self.subTest(torque=torque):
                cmd = replace(command, torque_cmd_nm=torque)
                builder = flatbuffers.Builder(1)
                builder.Finish(wire.fill_command(cmd, builder, 0))
                view = WireCmd.GetRootAs(builder.Output())
                self.assertEqual(view.TorqueCmdNm(), torque)
                self.assertEqual(codec.decode_cmd(view), cmd)
                self.assertEqual(view.Dq(), 0.)
                generated = GripperCmdT(protocolVersion=1, sessionId=cmd.session_id,
                    sequence=cmd.sequence, cmdId=cmd.cmd_id, inputStateId=cmd.input_state_id,
                    inputStateTsRealUs=cmd.input_state_ts_real_us,
                    tsClientCreatedUs=cmd.ts_client_created_us, tsClientSendUs=cmd.ts_client_send_us,
                    gripperType=1, side=2, q=cmd.q, dq=0., torqueCmdNm=torque)
                self.assertEqual(codec.decode_cmd(WireCmd.GetRootAs(pack(generated))), cmd)

    def test_info_config_sources_and_unknown_names_are_preserved(self):
        obj = GripperInfoT(tsInfoUs=10, tsStatePubUs=20, gripperType=1, side=1,
            openingMinM=0., openingMaxM=.0625, maxOpeningRateMS=.015625,
            holdTorqueNm=.25, openingMinSource=GripperLimitSource.PROTOCOL_DOCUMENT,
            openingMaxSource=GripperLimitSource.CONFIG, maxOpeningRateSource=GripperLimitSource.CONFIG,
            torqueLimitNm=.5, torqueLimitSource=GripperLimitSource.CONFIG,
            holdTorqueSource=GripperLimitSource.CONFIG)
        info = codec.decode_info(WireInfo.GetRootAs(pack(obj)))
        self.assertEqual((info.model, info.firmware), ('', ''))
        self.assertEqual((info.ts_info_us, info.ts_state_pub_us), (10, 20))
        self.assertEqual((info.max_opening_rate_m_s, info.hold_torque_nm, info.torque_limit_nm),
                         (.015625, .25, .5))
        self.assertEqual(info.hold_torque_source, GripperLimitSource.CONFIG)

    def test_optional_state_structs_validity_and_unknown_stamps_stay_independent(self):
        obj = GripperStateT(stateId=2**63+1, gripperType=1, side=1,
            tsStateRealUs=300, tsStatePubUs=400, tsAcquiredHwUs=22, tsIngestedUs=300, tsAssembledUs=350,
            sample=GripperSampleT(q=.03125, reportedTorqueNm=-.25, statusRaw=0x40), sampleValid=True,
            hostTarget=GripperHostTargetT(q=.0625, torqueCmdNm=.5), hostTargetValid=True,
            hostTargetSessionId=11, hostTargetSequence=12, hostTargetCmdId=13,
            traceSessionId=21, traceSequence=22, traceCmdId=23,
            tsCmdReceivedUs=500, tsCmdAcceptedUs=0, outputAllowed=True, inhibitReason=0)
        s = codec.decode_state(WireState.GetRootAs(pack(obj)))
        self.assertEqual((WireSample.SizeOf(), WireTarget.SizeOf()), (12, 8))
        self.assertEqual((s.ts_acquired_hw_us, s.ts_ingested_us, s.ts_assembled_us), (22, 300, 350))
        self.assertEqual((s.sample.q, s.sample.reported_torque_nm, s.sample.status_raw), (.03125, -.25, 0x40))
        self.assertEqual((s.host_target_session_id, s.trace_session_id), (11, 21))
        self.assertEqual((s.ts_cmd_accepted_us, s.ts_cmd_first_output_us,
                          s.ts_cmd_write_ack_us, s.ts_cmd_first_feedback_us), (0, 0, 0, 0))
        obj.sample = obj.hostTarget = None
        obj.sampleValid = obj.hostTargetValid = False
        missing = codec.decode_state(WireState.GetRootAs(pack(obj)))
        self.assertIsNone(missing.sample)
        self.assertIsNone(missing.host_target)

    def test_present_nan_or_zero_samples_are_not_replaced_by_absent_structs(self):
        obj = GripperStateT(sample=GripperSampleT(q=math.nan, reportedTorqueNm=math.nan), sampleValid=False,
                            hostTarget=GripperHostTargetT(q=0., torqueCmdNm=0.), hostTargetValid=True)
        decoded = codec.decode_state(WireState.GetRootAs(pack(obj)))
        self.assertTrue(math.isnan(decoded.sample.q))
        self.assertFalse(decoded.sample_valid)
        self.assertEqual((decoded.host_target.q, decoded.host_target.torque_cmd_nm), (0., 0.))

    def test_actual_root_subscribers_and_client_nullable_payload(self):
        node = RealPacketNode()
        client = GripperClient('left', node=node)
        self.addCleanup(client.close)
        obj = GripperInfoT(gripperType=1, side=1, openingMinM=0., openingMaxM=.0625,
            maxOpeningRateMS=.015625, holdTorqueNm=.25, openingMinSource=3,
            openingMaxSource=1, maxOpeningRateSource=1, torqueLimitNm=.5,
            torqueLimitSource=1, holdTorqueSource=1)
        node.emit('info', pack(obj))
        state = GripperStateT(stateId=999, gripperType=1, side=1, tsStateRealUs=300,
            sample=GripperSampleT(q=.03125, reportedTorqueNm=.25, statusRaw=0x40), sampleValid=True)
        node.emit('state', pack(state))
        for torque in (None, 0., -.25):
            command = client.publish_target(.03125, 0., torque_cmd_nm=torque)
            decoded = codec.decode_cmd(WireCmd.GetRootAs(node.payloads[-1]))
            self.assertEqual(decoded, command)
            self.assertEqual(decoded.input_state_ts_real_us, 300)
        self.assertEqual(len(node.payloads), 3)

    def test_missing_bindings_fail_before_creating_node(self):
        with patch.object(codec.importlib, 'import_module', side_effect=ImportError('missing')):
            with self.assertRaisesRegex(RuntimeError, 'matching T027'):
                GripperClient('left')

    def test_robot_info_and_independent_info_use_one_dto(self):
        from locomotion_aorta import GripperInfo, EndEffectorKind
        from locomotion_aorta._body_codec import decode_robot_info
        from lowlevel.RobotInfo import RobotInfo, RobotInfoT
        from lowlevel.EndEffectorCapability import EndEffectorCapabilityT
        from locomotion_aorta.gripper_types import GripperInfo as InfoDto
        self.assertIs(GripperInfo, InfoDto)
        info = GripperInfoT(gripperType=1, side=2, openingMinM=0., openingMaxM=.0625,
            maxOpeningRateMS=.015625, holdTorqueNm=-.25, openingMinSource=1,
            openingMaxSource=1, maxOpeningRateSource=1, torqueLimitNm=.5,
            torqueLimitSource=1, holdTorqueSource=1, tsStatePubUs=22)
        topic = codec.decode_info(WireInfo.GetRootAs(pack(info)))
        aggregate = RobotInfoT(protocolVersion=1, endEffectors=[EndEffectorCapabilityT(
            side=2, kind=EndEffectorKind.GRIPPER, configured=True, gripper=info)])
        result = decode_robot_info(RobotInfo.GetRootAs(pack(aggregate)))
        self.assertIsInstance(result.end_effectors[0].gripper, InfoDto)
        self.assertEqual(result.end_effectors[0].gripper, topic)
        self.assertEqual(result.end_effectors[0].gripper.hold_torque_nm, -.25)

    def test_capture_uses_gripper_roots_and_preserves_nullable_trace_keys(self):
        from locomotion_aorta import brainco_capture as capture
        bindings = capture.load_bindings()
        for torque in (None, 0., -.25):
            cmd = GripperCmdT(sessionId=17, sequence=18, gripperType=1, side=2,
                              q=.03125, dq=0., torqueCmdNm=torque)
            row = capture.decode('right_gripper_cmd', pack(cmd), bindings)
            self.assertEqual((row['q'], row['dq'], row['torque_cmd_nm']), (.03125, 0., torque))
            with self.assertRaisesRegex(ValueError, 'side differs'):
                capture.decode('left_gripper_cmd', pack(cmd), bindings)
        state = GripperStateT(gripperType=1, side=2, stateId=99,
            sample=GripperSampleT(q=float('nan')), sampleValid=False,
            hostTarget=GripperHostTargetT(q=0., torqueCmdNm=0.), hostTargetValid=True,
            hostTargetSessionId=10, hostTargetSequence=11, traceSessionId=12,
            traceSequence=13, tsCmdReceivedUs=100, tsCmdWriteAckUs=0)
        row = capture.decode('right_gripper_state', pack(state), bindings)
        self.assertIsNone(row['sample']['q'])
        self.assertTrue(row['nonfinite_feedback'])
        self.assertEqual((row['host_target_sequence'], row['trace_sequence']), (11, 13))
        self.assertEqual((row['host_target']['torque_cmd_nm'], row['ts_cmd_write_ack_us']), (0., 0))


if __name__ == '__main__':
    unittest.main(verbosity=2)
